ee:message.ee:set-payload:
%dw 2.0
import * from dw::core::Strings
output application/xml
var typePerson = vars.payloadInitial.OrderFulfilment.CustomerPartyAccount.TypeCode
var buType = if ( typePerson == p("rmca.typePerson.legal") ) p("rmca.buType.legal") else p("rmca.buType.natural")
var nameOrg1 = if ( sizeOf(vars.payloadInitial.OrderFulfilment.CustomerPartyAccount.Name)>40 ) substring(vars.payloadInitial.OrderFulfilment.CustomerPartyAccount.Name,0,40) else vars.payloadInitial.OrderFulfilment.CustomerPartyAccount.Name
var nameFirst = (vars.payloadInitial.OrderFulfilment.SalesOrderLine.AltKey filter $["AltKeyName"] == p("rmca.altFields.firstName"))[0].AltKeyValue
var lastName = (vars.payloadInitial.OrderFulfilment.SalesOrderLine.AltKey filter $["AltKeyName"] == p("rmca.altFields.lastName"))[0].AltKeyValue
var extAddressNumber = (vars.payloadInitial.OrderFulfilment.SalesOrderLine.AltKey filter $["AltKeyName"] == p("rmca.altFields.extAddressNumber"))[0].AltKeyValue
---
"Z_RM_RFC_CREATE_MASTER_DATA": {
	"import": {
		"BUSINESSPARTNEREXTERN": {
			"BU_TYPE": buType,
			"BPKIND": payload.BPKIND,
			"BPEXT": vars.payloadInitial.OrderFulfilment.CustomerPartyAccount.Identification.ID,
			"SEARCHTERM1": vars.payloadInitial.OrderFulfilment.CustomerPartyAccount.Custom.DocumentNumber,
			"TITLE_KEY": if ( buType == p("rmca.buType.legal") ) p("rmca.titleKey.legal") else p("rmca.titleKey.natural"),
			"BUPINFOREL": p("rmca.bupinforel")
		},
		"CENTRALDATA_ORGAN": {
			"NAME_ORG1": if ( buType == p("rmca.buType.legal") ) nameOrg1 else ""
		},
		"CENTRALDATA_PERSON": {
			"NAME_FIRST": if ( buType == p("rmca.buType.natural") ) nameFirst else "",
			"LASTNAME": if ( buType == p("rmca.buType.natural") ) lastName else "",
			"XSEXU": if ( buType == p("rmca.buType.natural") ) p("rmca.xsexu") else "",
			"NATIO": p("rmca.natio")
		},
		"SEL_CONTROL": {
			"ID_TRS": if ( p("rmca.subTypesForMod") contains("|$(vars.payloadInitial.OrderFulfilment.Custom.OrderSubType)|") ) p("rmca.idTrsM") else p("rmca.idTrsC"),
			"OBJETO": p("rmca.bp"),
			"CICLO": if ( vars.payloadInitial.BillingProcess.CustomerBill.InvoicingCycle != null and vars.payloadInitial.BillingProcess.CustomerBill.InvoicingCycle != '' ) vars.payloadInitial.BillingProcess.CustomerBill.InvoicingCycle else p("rmca.cycle")
		}
	},
	"tables": {
		"CTRACPARTNERDETAIL": {
		},
		"DIRECCIONES": {
			"row": {
				"CITY1": (vars.payloadInitial.OrderFulfilment.SalesOrderLine.AltKey filter $["AltKeyName"] == p("rmca.altFields.city"))[0].AltKeyValue,
				"REGION": substring(vars.payloadInitial.BillingProcess.Customer.ContactInfo.ContactAddress.DaneCode, 0, 2),
				"STREET": (vars.payloadInitial.OrderFulfilment.SalesOrderLine.AltKey filter $["AltKeyName"] == p("rmca.altFields.street"))[0].AltKeyValue,
				"COUNTRY": p("rmca.country"),
				"LANGU": p("rmca.langu"),
				"EXTADDRESSNUMBER": extAddressNumber
			}
		},
		"IDENTIFICACION": {
			"row": {
				"IDENTIFICATIONCATEGORY": payload.IDENTIFICATIONCATEGORY,
				"IDENTIFICATIONNUMBER": vars.payloadInitial.BillingProcess.Customer.DocumentNo
			}
		},
		"TELEFONOS": {
			"row": {
				"EXTADDRESSNUMBER": extAddressNumber,
				"TELEPHONE": (vars.payloadInitial.OrderFulfilment.SalesOrderLine.AltKey filter $["AltKeyName"] == p("rmca.altFields.phone"))[0].AltKeyValue,
				"TIPO": p("rmca.phoneType")
			}
		},
		"USO_DIRECCIONES": {
			"row": {
				"EXTADDRESSNUMBER": extAddressNumber,
				"ADDRESSTYPE": p("rmca.addressType")
			}
		}
	}
}

%dw 2.0
import * from dw::core::Strings
output application/xml
var sysOrgAK = (vars.payloadInitial.OrderFulfilment.SalesOrderLine.AltKey filter $["AltKeyName"] == p("rmca.altFields.sysOrgAK"))[0].AltKeyValue
var claimMethod = (vars.payloadInitial.OrderFulfilment.SalesOrderLine.AltKey filter $["AltKeyName"] == p("rmca.altFields.claimMethod"))[0].AltKeyValue
var extAddressNumber = (vars.payloadInitial.OrderFulfilment.SalesOrderLine.AltKey filter $["AltKeyName"] == p("rmca.altFields.extAddressNumber"))[0].AltKeyValue
---
{
	"Z_RM_RFC_CREATE_MASTER_DATA": {
		"import": {
			"BUSINESSPARTNEREXTERN": null,
			"CTRACCREATEINFO": {
				"LEGACY_ACCT": vars.payloadInitial.BillingProcess.CustomerBill.SuscriberId,
				"BPEXT": vars.payloadInitial.OrderFulfilment.CustomerPartyAccount.Identification.ID,
				"ACCT_NAME": if ( sizeOf(vars.payloadInitial.BillingProcess.Customer.FullName) > 35 ) substring(vars.payloadInitial.BillingProcess.Customer.FullName, 0, 35) else trim(vars.payloadInitial.BillingProcess.Customer.FullName)
			},
			"SEL_CONTROL": {
				"ID_TRS": if ( p("rmca.subTypesForMod") contains("|$(vars.payloadInitial.OrderFulfilment.Custom.OrderSubType)|") ) p("rmca.idTrsM") else p("rmca.idTrsC"),
				"OBJETO": p('rmca.ca'),
				"CICLO": vars.payloadInitial.BillingProcess.CustomerBill.InvoicingCycle
			}
		},
		"tables": {
			"CTRACPARTNERDETAIL": {
				"row": {
					"EXVKO": vars.payloadInitial.OrderFulfilment.CustomerPartyAccount.Identification.ID,
					"KTOKL": if ( sysOrgAK == p('rmca.salesForce') ) payload.homProcedimiento else if ( sysOrgAK == p('rmca.salesForceLTE') ) claimMethod else vars.homologates.KTOL,
					"EXTADDRESSNUMBER": extAddressNumber
				}
			}
		}
	}
}
